            originLatitude: null | number;
            /** Format: double */
            originLongitude: null | number;
            destination: string;
            /** Format: double */
            destinationLatitude: null | number;
            /** Format: double */
            destinationLongitude: null | number;
            /** Format: date-time */
            plannedDeliveryUtc: null | string;
